    "explanation": "Choice C is the best answer. The text describes the comfort rating scale: from −3 (very cold) to +3 (very hot), with 0 being neutral. Participant 20\ngave a −2 comfort rating, a full three points colder on the scale than the other two participants.\nChoice A is incorrect. This choice misreads the table. Participant 1 and participant 21 reported the same level of comfort, but participant 20’s\ncomfort level was three points lower. Choice B is incorrect. This choice doesn’t use data from the table. The table only shows us one survey, so\nwe don’t know if the participants’ ratings varied throughout the day. Choice D is incorrect. This choice misreads the table. Participant 1 and\nparticipant 21 reported the same level of comfort."
