    "passage": "Employing high-performance liquid chromatography—a process that uses pressurized water to separate material into its component molecules—\nastrochemist Yashiro Oba and colleagues analyzed two samples of the Murchison meteorite that landed in Australia as well as soil from the\nlanding zone of the meteorite to determine the concentrations of various organic molecules. By comparing the relative concentrations of types\nof molecules known as nucleobases in the Murchison meteorite with those in the soil, the team concluded that there is evidence that the\nnucleobases in the Murchison meteorite formed in space and are not the result of contamination on Earth.",
