    "image": "/questions/coeq/sat-coeq-94c726fb.png",
    "passage": "While doing research for a paper about copper mining, a student finds a table with information about four different countries. The student notes\nthat the country that mined 0.55 million metric tons of copper in 2020 had mined ______",
