    "correctAnswer": "D",
    "explanation": "Choice D is the best answer because it most effectively uses data from the table to complete the statement about the year when both museums\nhad the highest number of visits. The table shows the number of visits (in millions) from 2016 to 2019 to two museums: the National Museum of\nthe American Indian and the National Museum of African American History and Culture. It indicates that the highest number of visits to the\nNational Museum of the American Indian was 1.2 million in 2017 and that the highest number of visits to the National Museum of African\nAmerican History and Culture was 2.4 million, also in 2017.\nChoice A is incorrect because the table shows that in 2016, the National Museum of the American Indian had 1.1 million visits and that the\nNational Museum of African American History and Culture had 0.73 million visits, both of which are lower than the number of visits these\nmuseums had in 2017. Choice B is incorrect because the table shows that in 2018, the National Museum of the American Indian had 1.1 million\nvisits and that the National Museum of African American History and Culture had 1.9 million visits, both of which are lower than the number of\nvisits these museums had in 2017. Choice C is incorrect because the table shows that in 2019, the National Museum of the American Indian had\n0.96 million visits and that the National Museum of African American History and Culture had 2.0 million visits, both of which are lower than the\nnumber of visits these museums had in 2017."
