    "image": "/questions/coeq/sat-coeq-af125459.png",
    "passage": "Two kinds of clamshell tools used by Neanderthals were dug up in a cave on the western coast of Italy. Archaeologist Paola Villa and her\ncolleagues studied the tools and determined that Neanderthals either collected clams that had washed onto the beach or harvested clams from\nthe seafloor and then sharpened the shells to make tools. The highest number of tools made from clamshells that were collected from the beach\nwas found at a depth of ______",
