    "image": "/questions/coeq/sat-coeq-b29c520a.png",
    "passage": "A team of researchers used bacteria to create a biofuel (a renewable fuel produced from plants, algae, or other living materials). The team called\nthe new fuel POP biofuel. To determine how much energy is stored in POP biofuel compared to other fuels, the team calculated the fuels’ energy\ndensity, in megajoules per liter (MJ/L). The team found that the fuel with the highest energy density is ______",
