    "image": "/questions/coeq/sat-coeq-df34b586.png",
    "passage": "By the early 1900s, the Singer Corporation, a US sewing machine manufacturer founded in 1851, began to see rapidly increasing sales abroad,\nparticularly in Russia, Germany, and the United Kingdom. These markets were responsible for the bulk of Singer’s overseas sales, but demand for\nthe company’s machines in other countries also grew significantly in the early twentieth century. For instance, sales of their sewing machines in\n______",
