    "explanation": "Choice D is the best answer. The claim is that divided Congresses are necessary but insufficient—that is, we need divide Congresses, but they\nare not enough—to decrease government size, as measured by total federal outlays. This choice accurately expresses the supporting data from\nthe “change in total outlays” part of the graph. Within the data set, divided Congresses sometimes decreased total outlays, but undivided ones\nnever did.\nChoice A is incorrect. The claim is only about government size, as measured by total federal outlays—defense and nondefense outlays aren’t\nrelevant. Choice B is incorrect. The claim is only about government size as measured by total federal outlays—nondefense outlays aren’t relevant.\nChoice C is incorrect. The claim is only about government size as measured by total federal outlays—specific information about defense or\nnondefense outlays isn’t relevant."
